-- ATACJL v5: editable page-copy defaults and a development-friendly translation endpoint.
-- Run after migrate_v4.sql. Existing user-edited site settings are not overwritten,
-- except the known original LibreTranslate URL when no API key was configured.
ON DUPLICATE KEY UPDATE setting_value=setting_value;
UPDATE site_settings AS url_setting JOIN site_settings AS key_setting ON key_setting.setting_key='translation_api_key'
 SET url_setting.setting_value='https://translate.argosopentech.com/translate'
 WHERE url_setting.setting_key='translation_api_url' AND url_setting.setting_value='https://libretranslate.com/translate' AND key_setting.setting_value='';
